class Point { x: int = 0; y: int = 0; }
export function test(): int {
  let p: Point = { x: 1, y: 2 };
  p.x = p.x + 5;
  p.y = p.y + 2;
  return p.x * 10 + p.y;
}

class Mixed { i: int = 0; n: number = 0.0; b: boolean = false; s: string = ""; }
export function test(): int {
  let m: Mixed = { i: 3, n: 2.5, b: true, s: "jvm" };
  if (m.b === true && m.s === "jvm" && m.i === 3 && m.n > 2.0 && m.n < 3.0) { return m.i + 1; }
  return 0;
}

import * as console from "std/console"
class Pair { a: string = ""; b: string = ""; }
function tag(s: string): string { console.log(s); return s; }
export function test(): int {
  let p: Pair = { b: tag("second"), a: tag("first") };
  if (p.a === "first" && p.b === "second") { return 1; }
  return 0;
}

class Box { value: int = 0; }
export function test(): int {
  let holder: table = { item: { value: 1 } };
  let b: Box = holder.item;
  return b.value;
}

class Box { value: int = 0; }
export function test(): int {
  let holder: table = { item: null };
  let b: Box = holder.item;
  return b.value;
}

class A { x: int = 0; }
class B { x: int = 0; }
export function test(): int {
  let a: A = { x: 7 };
  let holder: table = { item: a };
  let b: B = holder.item;
  return b.x;
}

class P { b: boolean = false; }
export function test(): int {
  let xs: boolean[] = [true, false];
  let p: P = { b: xs[0] && xs[5] };
  return 1;
}

class Point { x: int = 1 + 2; }
export function test(): int {
  let p: Point = {};
  return p.x;
}

function noise(): null { return; }
function wrap(x: null): string { return "w"; }
class P { x: string = wrap(noise()); }
export function test(): int {
  let p: P = {};
  if (p.x === "w") { return 1; }
  return 0;
}

import * as console from "std/console"
class Box { x: int = 0; }
function note(s: string): null { console.log(s); return; }
function getBox(): Box { note("target"); return { x: 0 }; }
function make(v: null): int { note("make"); return 1; }
export function test(): int { getBox().x = make(note("value")); return 0; }

import * as console from "std/console"
class P { b: boolean = false; }
function getP(): P { console.log("target"); return { b: false }; }
export function test(): int {
  let xs: boolean[] = [true, false];
  getP().b = xs[0] && xs[5];
  return 1;
}
